from lib import *
recs=[
R(9810559,"Soupe aux carottes et aux lentilles",
"La soupe aux carottes et aux lentilles est un plat réconfortant, copieux, nutritif et facile à préparer.",
"6 portions","1 portion",
["1.5 tasse de lentilles rouges triées + rincées","1 oignon jaune finement haché","3 gousses d'ail pelées + émincées","2 livres de carottes pelées + grossièrement coupées (environ 6 grosses carottes)","1.5 livre de patates douces pelées + grossièrement coupées (environ 2 patates moyennes)","8 tasses de bouillon de légumes","2 cuillères à café de paprika fumé","1.5 cuillère à café de cumin","sel + poivre au goût","2-3 cuillères à soupe de jus de citron au goût, facultatif mais recommandé",["Garnitures facultatives","persil frais, coriandre, gingembre fraîchement râpé ou un filet d'huile d'olive"]],
["Mettez l'oignon et l'ail dans une grande marmite avec une cuillère à soupe d'eau ou de bouillon (ou d'huile si vous préférez) et faites sauter à feu moyen jusqu'à ce qu'ils soient translucides, environ 5 minutes.",
"Ajoutez ensuite tous les autres ingrédients, sauf le jus de citron. Portez la soupe à ébullition, puis réduisez le feu et laissez mijoter jusqu'à ce que les lentilles soient cuites et que les carottes et les patates douces soient tendres à la fourchette. Remuez de temps en temps.",
"Éteignez le feu et utilisez un mélangeur à immersion pour réduire la soupe en purée. Ajoutez ensuite le jus de citron, le sel et le poivre selon votre goût, et dégustez."],
["Commencez avec 8 tasses de bouillon, mais ajoutez-en si vous préférez une soupe plus liquide.","Au repos au réfrigérateur, la soupe épaissira. Vous pouvez ajouter de l'eau ou du bouillon au réchauffage si vous voulez la rendre plus liquide.","Les restes se conservent au réfrigérateur 3 à 4 jours ou congelés jusqu'à 3 mois."]),
R(9811020,"Vinaigrette déesse verte à l'avocat [sans huile]",
"Remplie de basilic frais, cette vinaigrette déesse verte apportera une touche de couleur et une saveur délicieuse à vos salades.",
"8 portions (donne environ 1 tasse)","2 c. à soupe",
["1 petit avocat pelé + noyau retiré","½ tasse de feuilles de basilic frais bien tassées","¼ tasse de ciboulette","¼ tasse de vinaigre de cidre de pomme","2 cuillères à soupe de jus de citron, environ la moitié d'un gros citron","2 cuillères à soupe de tahini","1 gousse d'ail pelée","1 cuillère à soupe de sirop d'érable, facultatif","1-2 cuillères à soupe d'eau au besoin pour allonger","sel + poivre au goût"],
["Mettez tous les ingrédients, sauf l'eau, dans un mélangeur et mixez jusqu'à obtenir une texture lisse. Ajoutez l'eau si vous préférez une consistance plus liquide et mixez de nouveau.",
"Conservez dans un contenant hermétique ou un bocal au réfrigérateur jusqu'à 1 semaine."],
["Pour une texture plus lisse et plus crémeuse avec une couleur uniforme, utilisez un mélangeur haute vitesse et mixez jusqu'à obtenir une purée complète. Si vous préférez voir des morceaux d'herbes dans la vinaigrette, utilisez un robot culinaire pour hacher d'abord finement tous les ingrédients (sans les liquides). Ajoutez ensuite les ingrédients liquides et mixez par impulsions pour combiner. Conservez votre vinaigrette dans un bocal en verre PROPRE ou un contenant hermétique. Gardez au réfrigérateur jusqu'à 1 semaine."]),
R(9811305,"Curry de courge musquée et de pois chiches",
"Ce curry de courge musquée et de pois chiches est plein de saveur et vous impressionnera à coup sûr !",
"6 portions","1 portion",
["2 livres de courge musquée pelée + coupée en cubes d'un demi-pouce (environ 6 tasses de cubes)","1 cuillère à soupe d'huile de coco ou de l'eau ou du bouillon pour faire sauter, pour une version sans huile","1 oignon jaune coupé en dés","2 carottes pelées + coupées en dés","1-2 piments rouges thaïlandais finement hachés, facultatif pour relever","6 gousses d'ail émincées","1 cuillère à soupe de gingembre frais râpé, environ un morceau d'un pouce","4 onces de pâte de curry rouge Thai Kitchen, environ 5 à 6 cuillères à soupe","2 cuillères à soupe de sauce soja ou de tamari pour une version sans gluten","2 cuillères à soupe de sirop d'érable","1 tasse de petits pois surgelés","1 tasse de bouillon de légumes","13.5 onces de lait de coco non sucré Thai Kitchen","1.5 tasse de pois chiches cuits ou en conserve","4 tasses de chou frisé, tiges retirées","2 cuillères à soupe de jus de lime, environ 1 grosse lime","sel + poivre au goût",["Facultatif","1 tasse de coriandre, grosses tiges retirées"],["Facultatif","1 tasse de basilic thaï haché"],["Facultatif","riz brun et/ou pain naan pour servir"]],
["Préchauffez le four à 425°F/218°C en mode rôtissage par convection et recouvrez une plaque de cuisson de papier parchemin.",
"Disposez vos cubes de courge en une seule couche sur votre plaque et saupoudrez de sel et de poivre. Faites ensuite rôtir de 25 à 30 minutes, ou jusqu'à ce qu'ils soient légèrement dorés et tendres à la fourchette. Mettez de côté.",
"Pendant ce temps, faites fondre l'huile de coco (si vous en utilisez) dans une grande poêle profonde (ou une cocotte), puis ajoutez l'oignon et les carottes et faites sauter jusqu'à ce qu'ils soient ramollis et légèrement caramélisés, environ 8 à 10 minutes. Ajoutez ensuite les piments, l'ail et le gingembre et remuez constamment jusqu'à ce que le tout soit parfumé, environ 30 secondes.",
"Ajoutez la pâte de curry rouge, la sauce soja, le sirop d'érable, les petits pois, le bouillon, le lait de coco, les pois chiches et le chou frisé dans la poêle et laissez mijoter de 8 à 10 minutes.",
"Éteignez ensuite le feu et ajoutez le jus de lime, la coriandre et le basilic si vous en utilisez, puis incorporez les cubes de courge musquée rôtis. Goûtez et ajoutez du sel et du poivre, si nécessaire.",
"Servez ce curry de courge musquée et de pois chiches avec du riz, du pain naan ou des chips de pita."],
["Si vous n'avez pas de four à convection, utilisez 425°F/218°C en mode cuisson (ou rôtissage, si vous l'avez). Il faudra de 5 à 10 minutes de plus pour rôtir, selon la taille de vos cubes. Coupez vos cubes de courge musquée de la façon la plus uniforme possible pour une cuisson uniforme. Les restes se conservent au réfrigérateur 3 à 4 jours ; réchauffez-les sur la cuisinière. Vous pouvez les congeler dans un contenant hermétique allant au congélateur jusqu'à 3 mois, mais la texture des légumes sera plus molle."]),
R(9814933,"Trempette végétalienne façon gâteau au fromage et pain d'épices",
"Une fantastique trempette végétalienne façon gâteau au fromage, remplie de saveurs réconfortantes de pain d'épices.",
"8 portions","1 portion",
["1 tasse de lait de coco léger en conserve","2 tasses de noix de cajou crues ou d'amandes blanchies","¼ tasse de sucre de coco non raffiné","2 cuillères à soupe de mélasse moyenne ou foncée","1 cuillère à café de gingembre moulu","1 cuillère à café de cannelle","⅛ cuillère à café de muscade"],
["Mettez tous les ingrédients dans un mélangeur haute vitesse et mixez jusqu'à obtenir une texture lisse et crémeuse.",
"Réfrigérez la trempette au moins 1 heure avant de la servir avec des tranches de pomme, de l'ananas, des fraises, des guimauves, des biscuits au pain d'épices ou des craquelins Graham."],
["Si vous n'avez pas de mélangeur puissant, faites d'abord tremper vos noix de cajou dans de l'eau bouillante pendant 30 minutes. Cela les ramollira et les rendra plus faciles à mixer. Égouttez-les ensuite, mettez-les dans le mélangeur avec les autres ingrédients et mixez jusqu'à obtenir une texture lisse. La trempette végétalienne façon gâteau au fromage se conserve au réfrigérateur 4 à 5 jours ou congelée jusqu'à 2 mois. ASTUCE – congelez la trempette 1 à 2 heures et dégustez-la comme une crème glacée végétalienne au pain d'épices !"]),
R(9816028,"Soupe aux arachides et aux pois chiches à l'Instant Pot",
"Cette soupe aux arachides à l'Instant Pot contient de gros morceaux de légumes comme la patate douce, la courgette et les champignons, avec des pois chiches dans un bouillon crémeux aux arachides.",
"6 portions","1 portion",
["1 gros poivron rouge coupé en gros dés","3 tasses de courgettes coupées en gros dés, environ 2 courgettes moyennes","2.5 tasses de patate douce en dés, environ 1 patate moyenne","1 paquet de 8 onces de champignons cremini coupés en deux, ou en quatre s'ils sont très gros","1 tasse de maïs surgelé","1 boîte de 15 onces de pois chiches égouttés et rincés (environ 1.5 tasse)","4 tasses de bouillon de légumes faible en sodium","½ tasse de beurre d'arachide lisse","3 cuillères à soupe de tamari ou de sauce soja si vous n'évitez pas le gluten","1 cuillère à café de paprika fumé","1 cuillère à café de gingembre moulu","1 cuillère à café de poudre d'ail","½ cuillère à café de piment de Cayenne, facultatif, mais recommandé",["Garnitures facultatives","oignon vert"],["Garnitures facultatives","arachides hachées"],["Garnitures facultatives","coriandre fraîche"],["Garnitures facultatives","sriracha"],["Garnitures facultatives","tranches de jalapeño"],["Garnitures facultatives","quartiers de lime"]],
[["Instructions pour l'Instant Pot","Mettez tous les ingrédients dans votre Instant Pot et fermez le couvercle, en vous assurant que la soupape est en position de scellage. Réglez à haute pression pendant 2 minutes (il faudra environ 15 à 20 minutes pour atteindre la pression), puis relâchez rapidement la vapeur une fois la minuterie terminée."],["Instructions pour l'Instant Pot","Servez garni des garnitures désirées."],["Instructions pour la cuisinière","Mettez tous les ingrédients dans une grande marmite et portez à ébullition. Dès l'ébullition, baissez le feu et laissez mijoter de 12 à 15 minutes, jusqu'à ce que les légumes soient tendres à la fourchette"],["Instructions pour la cuisinière","Servez garni des garnitures désirées."]],
["Coupez vos morceaux de courgettes et de champignons plus gros, car ils cuisent plus vite et vous ne voulez pas qu'ils soient trop mous. La patate douce peut être un peu plus petite, car son temps de cuisson est plus long. Vous obtiendrez ainsi des légumes cuits uniformément. Relâchez rapidement la pression et retirez immédiatement le couvercle (lorsque cela est sans danger) une fois la cuisson sous pression terminée, pour éviter que les légumes ne cuisent trop. Les restes se conservent dans un contenant fermé au réfrigérateur jusqu'à 4 jours."]),
R(9822376,"Pesto au basilic et au citron sans noix [sans huile]",
"Parfumé et frais avec du basilic, de l'ail et du citron, c'est la recette de pesto sans huile parfaite dont vous avez besoin dans votre cuisine.",
"6 portions (donne 1 tasse)","1 portion",
["2 tasses de feuilles de basilic frais tassées","3-4 gousses d'ail pelées","2 cuillères à soupe de jus de citron, environ la moitié d'un gros citron","½ cuillère à café de sel de mer ou au goût","1-2 cuillères à soupe d'eau au besoin","2 tasses de coriandre fraîche tassée","3-4 gousses d'ail pelées","2 cuillères à soupe de jus de lime, environ 1 petite lime","1 jalapeño, épépiné pour moins de piquant","½ tasse de graines de tournesol crues non salées","½ cuillère à café de sel de mer","2-4 cuillères à soupe d'eau au besoin","2 tasses de persil frais tassé","3-4 gousses d'ail pelées","2 cuillères à soupe de jus de citron, environ la moitié d'un gros citron","½ tasse de tomates séchées","½ tasse d'olives kalamata","¼ cuillère à café de sel de mer","3-6 cuillères à soupe d'eau au besoin"],
["Mettez tous les ingrédients, sauf l'eau, dans un robot culinaire ou un mélangeur. Mixez jusqu'à obtenir une texture lisse en raclant les parois au besoin.",
"Ajoutez 1 cuillère à soupe d'eau à la fois, au besoin, pour obtenir la consistance désirée."],
["Vous pouvez conserver votre pesto dans un bocal au réfrigérateur pour le consommer en quelques jours. Ou le garder congelé jusqu'à 6 mois. Vous pouvez remplacer le basilic par n'importe quelle herbe, comme vous le souhaitez. Gardez simplement les mêmes proportions. Utilisez un robot culinaire pour un pesto avec un peu de texture, ou un mélangeur pour des résultats plus lisses. N'hésitez pas à doubler ou tripler la recette pour faire des portions à congeler pour plus tard. C'est particulièrement utile lorsque vous récoltez des herbes de votre jardin, afin de ne rien gaspiller."]),
R(9825585,"Sucettes glacées à la noix de coco et à la lime",
"Surtout acidulées avec une touche sucrée, ces sucettes glacées sont la gâterie d'été parfaite. Idéales pour se rafraîchir par temps chaud, elles ne contiennent que 3 ingrédients !",
"7 sucettes glacées","1 portion",
["400 ml de lait de coco léger","¼ tasse de jus de lime fraîchement pressé, d'environ 2 limes","1 avocat pelé et dénoyauté","2 cuillères à soupe de sirop d'érable, facultatif"],
["Mettez tous les ingrédients dans un mélangeur ou un robot culinaire et mixez jusqu'à obtenir une texture lisse. Versez ensuite délicatement le mélange dans des moules à sucettes glacées ou des gobelets en plastique. Congelez 6 heures ou toute la nuit.",
"Quand vous êtes prêt à déguster, passez l'extérieur du moule à sucettes sous l'eau tiède pendant quelques secondes et retirez délicatement la sucette de son moule."],
["Goûtez le mélange avant de le congeler. Prenez une cuillère et goûtez votre mélange de sucettes à la lime (ou de n'importe quelle sucette que vous préparez) pour vérifier le niveau de sucré, d'acidulé ou d'une autre saveur que vous pourriez vouloir ajouter. Vous pouvez toujours ajouter un peu plus de jus de lime avant de les congeler, si désiré. En séparant le moule de la sucette, faites attention de ne pas la casser ! Passez l'extérieur de votre moule à sucettes sous l'eau tiède dans l'évier de votre cuisine pendant quelques secondes, puis essayez de séparer délicatement. Utilisez un mouvement de côté à côté, ne tirez pas. Répétez jusqu'à ce que vous puissiez séparer facilement les sucettes à la lime de leur moule, sans les casser. S'il vous reste du mélange de sucettes à la lime à la fin, congelez le reste dans un bac à glaçons pour de petites gâteries. Remplissez vos moules presque jusqu'en haut. Les sucettes ne se dilateront que légèrement, alors ne laissez pas trop d'espace pour l'expansion, sinon votre bâtonnet ou votre couvercle ne tiendra pas bien la sucette. Veillez à congeler vos sucettes assez longtemps ! Le pire serait de retirer la sucette de son moule avant qu'elle soit complètement solide. J'aime leur accorder au moins 6 heures pour m'assurer qu'elles sont solides jusqu'au centre. Vous n'avez pas de moules à sucettes ? Pas de problème ! Utilisez des gobelets en papier et congelez-les, ouverture vers le haut, pendant environ 30 à 45 minutes. Plantez ensuite un bâtonnet au centre et poursuivez la congélation jusqu'à ce que ce soit complètement solide."]),
R(9827404,"Souper d'asperges sur une plaque de cuisson",
"Ce souper d'asperges sur une plaque de cuisson est un repas rapide, facile et savoureux, parfait pour les soirs de semaine chargés.",
"4 portions","1 portion",
["1 botte d'asperges (extrémités coupées et coupées en lanières de 2 pouces)","2 carottes (pelées + tranchées finement en lanières de 2 pouces)","1 oignon jaune (tranché)","1.5 tasse de pois chiches (cuits ou en conserve)","1 tasse de riz brun ou de quinoa (ou la céréale de votre choix)","1/4 tasse de jus de citron (environ 1 citron)","1/4 tasse de bouillon de légumes","1 cuillère à soupe de graines de sésame","1 cuillère à café de poudre d'ail","1 cuillère à café d'origan séché","sel + poivre (au goût)"],
["Préchauffez le four à 425℉/218℃ en mode cuisson par convection ou rôtissage si votre four a ce réglage, et recouvrez une grande plaque de cuisson de papier parchemin.",
"Mélangez tous les ingrédients de la marinade dans un petit bol. Mettez ensuite les légumes préparés et les pois chiches dans un grand bol et enrobez-les de marinade. Disposez les légumes en une seule couche sur votre plaque et faites rôtir environ 20 à 25 minutes, jusqu'à ce qu'ils soient dorés.",
"Pendant ce temps, préparez la céréale de votre choix. Faites cuire le riz, le quinoa ou la céréale de votre choix sur la cuisinière ou dans un cuiseur à riz selon les instructions de l'emballage. (REMARQUE : Utilisez du bouillon au lieu de l'eau pour cuire vos céréales afin d'ajouter de la saveur.)",
"Servez vos céréales cuites dans des bols avec les légumes et les pois chiches par-dessus."]),
]
save(4,recs)
